@import url('https://fonts.googleapis.com/css2?family=Antonio:wght@400;500;600;700&family=Inter:wght@400;500;600;700&family=JetBrains+Mono:wght@400;500;600;700&display=swap');

/* AC Milan DNA — San Siro night, rossoneri stripes, scudetto gold */
.theme-ac-milan {
  --bg: oklch(0.187 0 0);
  --surface: oklch(0.226 0 0);
  --surface-2: oklch(0.269 0 0);
  --fg: oklch(1.000 0 0);
  --fg-muted: oklch(0.686 0 0);
  --accent: oklch(0.622 0.253 28.9);
  --accent-fg: oklch(1.000 0 0);
  --accent-2: oklch(0.767 0.139 91.1);
  --line: oklch(1 0 0 / 13%);
  --success: oklch(0.615 0.143 147.4);
  --warning: oklch(0.768 0.158 81.3);
  --danger: oklch(0.55 0.2 27);
  --radius: 0.25rem;
  --radius-sm: 0.25rem;
  --radius-lg: 0.5rem;
  --radius-pill: 9999px;
  --shadow-1: 0 2px 6px oklch(0 0 0 / 45%);
  --shadow-2: 0 8px 24px oklch(0 0 0 / 55%);
  --shadow-3: 0 24px 56px oklch(0 0 0 / 65%);
  --glow: 0 0 0 1px color-mix(in oklab, var(--accent) 45%, transparent);
  --border-width: 1px;
  --blur-amount: 0px;
  --font-display: "Antonio", sans-serif;
  --font-body: "Inter", sans-serif;
  --font-mono: "JetBrains Mono", ui-monospace, monospace;
  --tracking-display: 0em;
  --label-transform: uppercase;
  --label-tracking: 0.1em;

  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-ac-milan h1,
.theme-ac-milan h2,
.theme-ac-milan h3 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-display);
}

/* signature */
.theme-ac-milan { --font-ui: var(--font-display); }
.theme-ac-milan h1, .theme-ac-milan h2 { text-transform: uppercase; }
.theme-ac-milan button { text-transform: uppercase; letter-spacing: 0.06em; }

.theme-ac-milan { background-image: repeating-linear-gradient(90deg, oklch(0.45 0.19 25 / 14%) 0 48px, transparent 48px 96px); }
.theme-ac-milan h1 { font-weight: 700; }
.theme-ac-milan h1::after { content: ""; display: block; height: 3px; width: 5rem; margin-top: 0.6rem; background: var(--accent-2); }

/* depth */
.theme-ac-milan thead th { background: oklch(0.15 0 0); color: oklch(1 0 0); text-transform: uppercase; letter-spacing: 0.1em; font-size: 0.78em; border-bottom: 3px solid var(--accent); }
.theme-ac-milan td { border-bottom: 1px solid var(--line); }
.theme-ac-milan tbody tr:hover { background: oklch(0.45 0.19 25 / 16%); }
.theme-ac-milan a { color: oklch(0.70 0.21 27); text-underline-offset: 3px; }
.theme-ac-milan a:hover { text-decoration-thickness: 2px; text-decoration-color: var(--accent-2); }
.theme-ac-milan ::selection { background: var(--accent); color: oklch(1 0 0); }
.theme-ac-milan input, .theme-ac-milan select, .theme-ac-milan textarea { background: oklch(0.16 0 0); }
.theme-ac-milan input:focus-visible, .theme-ac-milan select:focus-visible, .theme-ac-milan textarea:focus-visible { outline: 2px solid var(--accent); outline-offset: 1px; }
/* scudetto trim on keycaps */
.theme-ac-milan kbd { background: oklch(0.16 0 0); border: 1px solid var(--line); border-bottom: 3px solid var(--accent-2); border-radius: var(--radius-sm); padding: 0.1em 0.45em; font-family: var(--font-mono); }
.theme-ac-milan ::-webkit-scrollbar { width: 10px; height: 10px; }
.theme-ac-milan ::-webkit-scrollbar-track { background: oklch(0.15 0 0); }
.theme-ac-milan ::-webkit-scrollbar-thumb { background: oklch(0.50 0.20 27); border-radius: 5px; border: 2px solid oklch(0.15 0 0); }
.theme-ac-milan ::-webkit-scrollbar-thumb:hover { background: var(--accent); }
.theme-ac-milan .label-caps { color: var(--accent-2); }
/* rossoneri shirt stripes on framed panels */
.theme-ac-milan .themed-border { border-image: repeating-linear-gradient(90deg, oklch(0.55 0.22 27) 0 8px, oklch(0.12 0 0) 8px 16px) 1; }
.theme-ac-milan button:active { transform: translateY(1px); }

/* alt mode: away kit (2026-27 real kit / NBA Association Edition) */
.theme-ac-milan.alt-mode {
  --bg: oklch(0.985 0.005 95.1);
  --surface: oklch(1.000 0 0);
  --surface-2: oklch(0.948 0.011 95.2);
  --fg: oklch(0.199 0.012 73.2);
  --fg-muted: oklch(0.519 0.020 84.6);
  --accent: oklch(0.199 0.012 73.2);
  --accent-fg: oklch(0.985 0.005 95.1);
  --accent-2: oklch(0.731 0.115 85.0);
  --line: oklch(0.912 0.019 93.7);
  --shadow-1: 0 1px 2px oklch(0 0 0 / 8%);
  --shadow-2: 0 6px 20px -8px oklch(0 0 0 / 15%);
  --shadow-3: 0 20px 50px -16px oklch(0 0 0 / 20%);
}
.theme-ac-milan.alt-mode { background-image: none; }
.theme-ac-milan.alt-mode h1::after { background: #c9a24b; }
.theme-ac-milan.alt-mode h1 { color: #191510; }
.theme-ac-milan.alt-mode input, .theme-ac-milan.alt-mode select, .theme-ac-milan.alt-mode textarea { background: oklch(1 0 0); border: 1px solid var(--line); }
.theme-ac-milan.alt-mode kbd { background: var(--surface-2); color: var(--fg); }
.theme-ac-milan.alt-mode a { color: oklch(0.50 0.20 27); }
.theme-ac-milan.alt-mode ::-webkit-scrollbar-track { background: var(--surface-2); }
.theme-ac-milan.alt-mode ::-webkit-scrollbar-thumb { border-color: var(--surface-2); }

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);

  /* Full app surface: sidebar, charts, app-level font + shadow + tracking vars.
     These are what real products (shadcn full kit, RootCX-style UI kits) consume —
     without them a retrofit looks half-themed. */
  --sidebar: var(--surface-2);
  --sidebar-foreground: var(--fg);
  --sidebar-primary: var(--accent);
  --sidebar-primary-foreground: var(--accent-fg);
  --sidebar-accent: color-mix(in oklab, var(--accent) 12%, var(--surface-2));
  --sidebar-accent-foreground: var(--fg);
  --sidebar-border: var(--line);
  --sidebar-ring: var(--accent);

  --chart-1: var(--accent);
  --chart-2: var(--accent-2);
  --chart-3: var(--success);
  --chart-4: var(--warning);
  --chart-5: var(--danger);

  --font-sans: var(--font-body);
  --font-heading: var(--font-app, var(--font-display));
  --font-serif: var(--font-display);

  --shadow-2xs: var(--shadow-1);
  --shadow-xs: var(--shadow-1);
  --shadow-sm: var(--shadow-1);
  --shadow: var(--shadow-2);
  --shadow-md: var(--shadow-2);
  --shadow-lg: var(--shadow-3);
  --shadow-xl: var(--shadow-3);
  --shadow-2xl: var(--shadow-3);

  --tracking-normal: 0em;
}

/* Base experience: make the theme own the canvas and native elements even in
   apps that never adopted semantic classes. Scoped to the theme wrapper. */
[class*="theme-"] {
  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}
[class*="theme-"] :is(h1, h2, h3, h4) { font-family: var(--font-display); }
[class*="theme-"] :is(code, pre, kbd, samp) { font-family: var(--font-mono); }
[class*="theme-"] ::selection { background: color-mix(in oklab, var(--accent) 30%, transparent); }

/* OPT-IN HARD MODE — add "sf-enforce" beside the theme class when the host app
   bakes font/shadow/radius literals into its compiled utilities (a var bridge
   cannot beat a literal). Targeted !important, fonts and surfaces only. */
[class*="theme-"].sf-enforce { font-family: var(--font-body) !important; }
[class*="theme-"].sf-enforce :is(h1, h2, h3, h4, [class*="font-heading"]) {
  font-family: var(--font-app, var(--font-display)) !important;
  letter-spacing: var(--tracking-display) !important;
}
/* Data stays data: metrics/KPIs keep the body face with aligned lining figures.
   The display face is for headlines ONLY — never on numbers. Opt specific
   elements INTO the display face with data-sf="display". */
[class*="theme-"] :is([class*="text-2xl"], [class*="text-3xl"], [class*="text-4xl"], [class*="text-5xl"]) {
  font-variant-numeric: lining-nums tabular-nums;
}
[class*="theme-"].sf-enforce [data-sf="display"] {
  font-family: var(--font-display) !important;
  letter-spacing: var(--tracking-display) !important;
}
[class*="theme-"] :is(.sf-num, [data-sf="num"]) {
  font-family: var(--font-body) !important;
  font-variant-numeric: lining-nums tabular-nums;
}
[class*="theme-"].sf-enforce :is(button, [role="button"]) { font-family: var(--font-ui, var(--font-body)) !important; }
[class*="theme-"].sf-enforce :is(code, pre, kbd) { font-family: var(--font-mono) !important; }
[class*="theme-"].sf-enforce :is(.bg-card, [class*="card"]) {
  box-shadow: var(--shadow-2) !important;
  border-radius: var(--radius-lg) !important;
  border: var(--border-width) solid var(--line) !important;
}
[class*="theme-"].sf-enforce :is([class*="shadow-sm"], [class*="shadow-md"]) { box-shadow: var(--shadow-1) !important; }
[class*="theme-"].sf-enforce :is([class*="shadow-lg"], [class*="shadow-xl"]) { box-shadow: var(--shadow-3) !important; }
